<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import MarkdownBlock from '../components/MarkdownBlock.vue'
import { commentTrackerIssue, deleteTrackerMemory, getTrackerIssue, listTrackerIssues, listTrackerMemories, listTrackerRepos, updateTrackerIssue, updateTrackerMemory } from '../api/client'
import type { TrackerIssue, TrackerIssueView, TrackerMemory, TrackerRepo } from '../api/types'
import { trackerIssueMatches, trackerRepoLabel } from '../utils/trackerView'

type Row = TrackerIssue & { data: Record<string, any> }
type MemRow = TrackerMemory & { data: Record<string, any> }
const route = useRoute(); const router = useRouter()
const repos = ref<TrackerRepo[]>([]); const trackerId = ref(''); const tab = ref<'issues'|'memories'>('issues')
const issues = ref<Row[]>([]); const memories = ref<MemRow[]>([]); const selected = ref<TrackerIssueView|null>(null); const selectedRow = ref<Row|null>(null); const selectedMemory = ref<MemRow|null>(null)
const loading = ref(false); const error = ref(''); const query = ref(''); const typeFilter = ref(''); const tagFilter = ref(''); const statuses = ref(['open','in_progress','blocked'])
const editTitle = ref(''); const editStatus = ref(''); const editPriority = ref(0); const editDescription = ref(''); const comment = ref(''); const memoryDraft = ref(''); const saving = ref(false)
const repo = computed(() => repos.value.find((item) => item.tracker_id === trackerId.value))
const parse = (raw: string): Record<string, any> => { try { return JSON.parse(raw) } catch { return {} } }
const filteredIssues = computed(() => issues.value.filter((row) => trackerIssueMatches(row.data, row.id, statuses.value, typeFilter.value, tagFilter.value, query.value)))
const filteredMemories = computed(() => memories.value.filter((row) => !query.value.trim() || `${row.id} ${row.data.content??''}`.toLowerCase().includes(query.value.trim().toLowerCase())))
async function loadRepos(){ const out=await listTrackerRepos(); repos.value=out.repos??[]; const recent=[...repos.value].sort((a,b)=>b.last_sync_at-a.last_sync_at)[0]; if(!trackerId.value||!repos.value.some((r)=>r.tracker_id===trackerId.value)) trackerId.value=recent?.tracker_id??'' }
async function load(){ if(!trackerId.value)return; loading.value=true; error.value=''; try { const [a,b]=await Promise.all([listTrackerIssues(trackerId.value),listTrackerMemories(trackerId.value)]); issues.value=(a.issues??[]).map((x)=>({...x,data:parse(x.body_json)})); memories.value=(b.memories??[]).filter((x)=>!x.deleted).map((x)=>({...x,data:parse(x.body_json)})) } catch(e){error.value=e instanceof Error?e.message:String(e)} finally{loading.value=false} }
async function changeRepo(){selected.value=null;selectedMemory.value=null;await load()}
async function openIssue(row:Row){selectedRow.value=row;selected.value=await getTrackerIssue(trackerId.value,row.id);editTitle.value=selected.value.title;editStatus.value=selected.value.status;editPriority.value=selected.value.priority;editDescription.value=selected.value.description??'';void router.replace({query:{issue:row.id}})}
function closeDrawer(){selected.value=null;selectedRow.value=null;void router.replace({query:{}})}
async function saveIssue(){if(!selectedRow.value||saving.value)return;saving.value=true;try{await updateTrackerIssue(trackerId.value,selectedRow.value.id,{title:editTitle.value,status:editStatus.value,priority:editPriority.value,description:editDescription.value,expected_rev:selectedRow.value.rev});await load();const row=issues.value.find((x)=>x.id===selectedRow.value?.id);if(row)await openIssue(row)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}
async function addComment(){if(!selectedRow.value||!comment.value.trim())return;try{await commentTrackerIssue(trackerId.value,selectedRow.value.id,comment.value.trim());comment.value='';await openIssue(selectedRow.value)}catch(e){error.value=e instanceof Error?e.message:String(e)}}
function openMemory(row:MemRow){selectedMemory.value=selectedMemory.value?.id===row.id?null:row;memoryDraft.value=String(row.data.content??'')}
async function saveMemory(){if(!selectedMemory.value)return;try{await updateTrackerMemory(trackerId.value,selectedMemory.value.id,{content:memoryDraft.value,expected_rev:selectedMemory.value.rev});selectedMemory.value=null;await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}}
async function removeMemory(row:MemRow){try{await deleteTrackerMemory(trackerId.value,row.id);await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}}
function toggleStatus(s:string){statuses.value=statuses.value.includes(s)?statuses.value.filter((x)=>x!==s):[...statuses.value,s]}
function repoText(r:TrackerRepo){return trackerRepoLabel(r)}
onMounted(async()=>{try{await loadRepos();await load();const id=String(route.query.issue||'');const row=issues.value.find((x)=>x.id===id);if(row)await openIssue(row)}catch(e){error.value=e instanceof Error?e.message:String(e)}})
</script>

<template>
  <main class="tracker-page">
    <header class="page-head"><div><p class="eyebrow mono">TRACKER</p><h1 class="title mono">Issues</h1></div><button class="primary-btn mono" type="button" :disabled="loading||!trackerId" @click="load">刷新</button></header>
    <section class="meta-panel"><label class="repo-field mono"><span>仓库</span><select v-model="trackerId" class="filter-select" @change="changeRepo"><option value="">请选择已登记仓库</option><option v-for="r in repos" :key="r.tracker_id" :value="r.tracker_id">{{ repoText(r) }}</option></select></label><div v-if="repo" class="sync-summary mono"><span>上次同步 {{ repo.last_sync_at ? new Date(repo.last_sync_at*1000).toLocaleString() : '—' }}</span><span>{{ repo.sync_summary || '暂无同步冲突摘要' }}</span></div></section>
    <section v-if="repos.length===0" class="empty-panel mono"><span>暂无已登记仓库</span><code>gofer repo init</code><code>gofer repo sync</code></section>
    <template v-else>
      <nav class="tabs mono"><button type="button" :class="{active:tab==='issues'}" @click="tab='issues'">Issues</button><button type="button" :class="{active:tab==='memories'}" @click="tab='memories'">Memories</button></nav>
      <section class="filter-panel"><div v-if="tab==='issues'" class="chips mono"><button v-for="s in ['open','in_progress','blocked','closed']" :key="s" type="button" class="chip" :class="[`chip--${s}`,{selected:statuses.includes(s)}]" @click="toggleStatus(s)">{{ s }}</button></div><label class="filter-field">类型<input v-model="typeFilter" class="filter-input mono" placeholder="全部" /></label><label class="filter-field">标签<input v-model="tagFilter" class="filter-input mono" placeholder="标签" /></label><label class="filter-field query-field">关键字<input v-model="query" class="filter-input mono" placeholder="ID、标题或内容" /></label></section>
      <p v-if="error" class="error-panel mono">{{ error }}</p><p v-else-if="loading" class="loading mono">加载中…</p>
      <section v-if="tab==='issues'&&!loading" class="table"><div class="thead mono"><span>ID</span><span>标题</span><span>状态</span><span>优先级</span><span>类型</span><span>标签</span><span>更新</span></div><button v-for="row in filteredIssues" :key="row.id" type="button" class="trow" @click="openIssue(row)"><span class="mono">{{ row.id }}</span><strong>{{ row.data.title||'—' }}</strong><span>{{ row.data.status||'—' }}</span><span>{{ row.data.priority??0 }}</span><span>{{ row.data.type||'—' }}</span><span class="muted">{{ (row.data.tags??[]).join(' · ')||'—' }}</span><span class="mono">{{ row.data.updated_at||row.updated_at }}</span></button><div v-if="filteredIssues.length===0" class="table-empty mono">暂无匹配 issue</div></section>
      <section v-if="tab==='memories'&&!loading" class="memory-list"><article v-for="row in filteredMemories" :key="row.id" class="memory-card"><button type="button" class="memory-head" @click="openMemory(row)"><span class="mono">{{ row.id }}</span><span>{{ (row.data.tags??[]).join(' · ')||'无标签' }}</span><span class="mono">{{ row.data.updated_at||row.updated_at }}</span></button><p class="memory-summary">{{ String(row.data.content??'').slice(0,180) }}</p><div v-if="selectedMemory?.id===row.id" class="memory-expanded"><MarkdownBlock :text="String(row.data.content??'')" /><textarea v-model="memoryDraft" class="editor-input" rows="6" /><div class="actions"><button class="primary-btn" type="button" @click="saveMemory">保存</button><button class="secondary-btn" type="button" @click="removeMemory(row)">删除</button></div></div></article><div v-if="filteredMemories.length===0" class="empty-panel mono">暂无 memory</div></section>
    </template>
    <div v-if="selected" class="backdrop" @click="closeDrawer"></div><aside v-if="selected" class="drawer"><header class="drawer-head"><div><p class="eyebrow mono">ISSUE DETAIL</p><h2>{{ selected.id }}</h2></div><button class="drawer-close" type="button" @click="closeDrawer">×</button></header><div class="drawer-body"><label>标题<input v-model="editTitle" class="editor-input" /></label><div class="drawer-grid"><label>状态<select v-model="editStatus" class="filter-select"><option>open</option><option>in_progress</option><option>blocked</option><option>closed</option></select></label><label>优先级<input v-model.number="editPriority" class="editor-input" type="number" min="0" max="4" /></label></div><label>描述<textarea v-model="editDescription" class="editor-input" rows="5" /></label><MarkdownBlock v-if="selected.description" :text="selected.description" /><div class="actions"><button class="primary-btn" type="button" :disabled="saving" @click="saveIssue">保存</button></div><h3>notes</h3><ul><li v-for="n in selected.notes??[]" :key="`${n.at}-${n.by}`"><span class="mono">{{ n.at }} · {{ n.by }}</span><p>{{ n.text }}</p></li></ul><h3>comments</h3><ul><li v-for="c in selected.comments??[]" :key="`${c.at}-${c.by}`"><span class="mono">{{ c.at }} · {{ c.by }}</span><p>{{ c.text }}</p></li></ul><textarea v-model="comment" class="editor-input" rows="3" placeholder="发表评论" /><button class="secondary-btn" type="button" @click="addComment">评论</button></div></aside>
  </main>
</template>

<style scoped>
.tracker-page{max-width:1240px;margin:0 auto}.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.eyebrow{color:var(--queue);font-size:10px;letter-spacing:.18em;margin:0}.title{color:var(--paper);font-size:18px;margin:0}.meta-panel,.filter-panel,.empty-panel{border:1px solid var(--line);border-radius:var(--radius);background:var(--panel);padding:12px 14px}.meta-panel{display:flex;align-items:flex-end;gap:18px;margin-bottom:14px}.repo-field,.filter-field{display:flex;flex-direction:column;gap:5px;color:var(--queue);font-size:11px}.repo-field{min-width:360px}.sync-summary{display:flex;flex-direction:column;gap:4px;color:var(--queue);font-size:11px}.filter-select,.filter-input,.editor-input{background:var(--panel);color:var(--paper);border:1px solid var(--line);border-radius:var(--radius);padding:6px 8px;font-size:12px}.filter-select:focus,.filter-input:focus,.editor-input:focus{border-color:var(--phosphor);outline:none}.primary-btn,.secondary-btn{border-radius:var(--radius);padding:5px 10px;font-size:12px}.primary-btn{background:var(--phosphor);color:var(--ink);border:1px solid var(--phosphor);font-weight:600}.secondary-btn{background:transparent;color:var(--phosphor);border:1px solid var(--line)}.tabs{display:flex;gap:18px;border-bottom:1px solid var(--line);margin-bottom:12px}.tabs button{color:var(--queue);background:transparent;border:0;border-bottom:2px solid transparent;padding:7px 3px}.tabs button.active{color:var(--phosphor);border-bottom-color:var(--phosphor)}.filter-panel{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:12px}.query-field{flex:1 1 220px}.chips{display:flex;gap:6px;flex-wrap:wrap}.chip{border:1px solid var(--line);border-radius:999px;padding:5px 9px;background:transparent;color:var(--queue);font:inherit;opacity:.55}.chip.selected{opacity:1}.chip--open.selected{color:var(--done);border-color:var(--done)}.chip--in_progress.selected{color:var(--run);border-color:var(--run)}.chip--blocked.selected{color:var(--fail);border-color:var(--fail)}.table{border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}.thead,.trow{display:grid;grid-template-columns:130px minmax(180px,1.4fr) 120px 70px 100px minmax(120px,1fr) 150px;gap:10px;align-items:center;padding:9px 12px}.thead{background:var(--panel);color:var(--queue);font-size:11px;letter-spacing:.06em}.trow{width:100%;text-align:left;background:transparent;border:0;border-top:1px solid var(--line);color:var(--paper);font-size:12px}.trow:hover{background:var(--panel)}.muted,.loading,.table-empty{color:var(--queue)}.table-empty{text-align:center;padding:28px}.empty-panel{display:flex;justify-content:center;align-items:center;gap:10px;min-height:150px;color:var(--queue)}.empty-panel code{color:var(--phosphor);background:var(--term-bg);border:1px solid var(--line);padding:5px 8px;border-radius:var(--radius)}.error-panel{color:var(--fail);border:1px solid var(--fail);padding:8px}.memory-card{border:1px solid var(--line);border-radius:var(--radius);background:var(--panel);padding:10px 12px;margin-bottom:8px}.memory-head{width:100%;display:flex;justify-content:space-between;gap:12px;color:var(--paper);background:transparent;border:0;text-align:left}.memory-head span:last-child{color:var(--queue)}.memory-summary{color:var(--queue);margin:8px 0 0}.memory-expanded{margin-top:10px}.actions{display:flex;gap:8px;margin-top:10px}.backdrop{position:fixed;inset:0;background:color-mix(in srgb,var(--ink) 64%,transparent);z-index:70}.drawer{position:fixed;top:0;right:0;bottom:0;width:min(520px,92vw);z-index:80;background:var(--panel);border-left:1px solid var(--line);box-shadow:-8px 0 24px color-mix(in srgb,var(--ink) 45%,transparent);overflow:auto}.drawer-head{display:flex;justify-content:space-between;align-items:flex-start;padding:16px;border-bottom:1px solid var(--line)}.drawer-head h2{margin:4px 0 0;font-size:16px}.drawer-close{border:1px solid var(--line);background:transparent;color:var(--paper);border-radius:var(--radius);font-size:20px;line-height:1;width:28px;height:28px}.drawer-body{padding:16px}.drawer-body label{display:flex;flex-direction:column;gap:5px;color:var(--queue);font-size:11px;margin-bottom:12px}.drawer-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.drawer-body h3{color:var(--queue);font:12px var(--font-mono);letter-spacing:.08em;text-transform:uppercase}.drawer-body ul{padding-left:18px}.drawer-body li{margin:10px 0}.drawer-body li span{color:var(--queue);font-size:10px}.drawer-body li p{margin:3px 0;color:var(--paper)}
@media (max-width:639px){.meta-panel{flex-direction:column;align-items:stretch}.repo-field{min-width:0}.thead,.trow{grid-template-columns:100px minmax(150px,1fr) 100px 55px}.thead span:nth-child(n+5),.trow>span:nth-child(n+5){display:none}}
</style>
